// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { clearLocalAuthStorage } from '@/lib/localAuthStorageKey';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
// Prefer the explicit anon key. A stale VITE_SUPABASE_PUBLISHABLE_KEY (e.g. left over
// from the old cloud project) must never win — it is signed with a different JWT secret,
// so the self-hosted gateway rejects it with 401 on every request, including login.
const SUPABASE_PUBLISHABLE_KEY =
  import.meta.env.VITE_SUPABASE_ANON_KEY ||
  import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
  console.error(
    "Supabase env missing: set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY.",
  );
}

// Loud guard: cloud project keys carry a `ref` claim; self-hosted anon keys do not.
// If a cloud key is baked into this build it will 401 — surface it instead of failing silently.
if (SUPABASE_PUBLISHABLE_KEY) {
  try {
    const payload = SUPABASE_PUBLISHABLE_KEY.split(".")[1];
    const claims = JSON.parse(atob(payload.replace(/-/g, "+").replace(/_/g, "/")));
    if (claims?.ref) {
      console.error(
        `Supabase anon key is for cloud project "${claims.ref}" but VITE_SUPABASE_URL is ${SUPABASE_URL}. ` +
          "This key will be rejected with 401. Set VITE_SUPABASE_ANON_KEY to the self-hosted anon key.",
      );
    }
  } catch {
    /* ignore decode errors */
  }
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
  },
});

if (typeof window !== "undefined") {
  supabase.auth.onAuthStateChange((event, session) => {
    if (
      (event === "TOKEN_REFRESHED" && !session) ||
      (event === "SIGNED_OUT" && !session)
    ) {
      try {
        // Scoped to this project's own key only — see src/lib/localAuthStorageKey.ts.
        // Must never sweep the separate Cloud maintenance client's session.
        clearLocalAuthStorage();
      } catch {
        // ignore storage errors
      }
    }
  });
}